   const items=[...new Map(assets.filter(a=>includeFx?core.quoteEligible(a):['TW','US'].includes(a.market)).map(a=>[a.market+':'+a.symbol.toUpperCase(),{market:a.market,symbol:a.symbol.toUpperCase()}])).values()];
